pA = pV;
        for (j = 0; j < dim_vec; j++)
        {
            q15_t inA = *pA++;
            q15_t inB = *pB++;
            ip_out += inA * inB;
        }
        *pO++ = (q15_t)__SSAT((ip_out >> out_shift), 16);

rowCnt--;
    }

#endif /* ARM_MATH_DSP */

/* Return to ARM_MATH_SUCCESS */
    return (ARM_MATH_SUCCESS);
}

