            rhs_0 += 16;
        }
        rhs += rhs_cols;

const int32_t offsets = rhs_sum_0 * lhs_offset;
        acc_0 = __QADD(acc_0, offsets);
        acc_0 = arm_nn_requantize(acc_0, dst_multiplier, dst_shift);

