#include "arm_nnfunctions.h"
#include "arm_nnsupportfunctions.h"

#define ACCUM_BITS 12

/**
 *  @ingroup groupNN
 */

/**
 * @addtogroup Softmax
 * @{
 */
void arm_softmax_u8(const uint8_t *input,
                    const int32_t num_rows,
                    const int32_t row_size,
                    const int32_t mult,
                    const int32_t shift,
                    const int32_t diff_min,
                    uint8_t *output)
{
    const int32_t mask = (1 << shift);

int32_t col = 0;
    int32_t row_idx;

for (row_idx = 0; row_idx < num_rows; ++row_idx)
    {
        // Find the maximum value in order to ensure numerical stability
        uint8_t max = *input;

for (col = 1; col < row_size; ++col)
        {
            max = MAX(max, input[col]);
        }

int32_t diff = 0;
        int32_t sum = 0;

for (col = 0; col < row_size; ++col)
        {
            diff = input[col] - max;
            if (diff >= diff_min)
            {
                sum += DIV_POW2(EXP_ON_NEG(MUL_SAT(diff * mask, mult)), ACCUM_BITS);
            }
        }

const int32_t headroom = __CLZ((uint32_t)sum);
        const int32_t bits_over_unit = ACCUM_BITS - headroom + 23;
        const int32_t shifted_scale = ONE_OVER1((sum << headroom) - (1 << 31));

for (col = 0; col < row_size; ++col)
        {
            diff = input[col] - max;
            if (diff >= diff_min)
            {
                const int32_t res =
                    DIV_POW2(MUL_SAT(shifted_scale, EXP_ON_NEG(MUL_SAT(diff * mask, mult))), bits_over_unit);
                output[col] = (uint8_t)CLAMP(res, (int32_t)255, (int32_t)0);
            }
            else
            {
                output[col] = 0;
            }
        }
        input += row_size;
        output += row_size;
    }
}
