  blkCnt = blockSize % 0x4U;

#else

/* Initialize blkCnt with number of samples */
  blkCnt = blockSize;

#endif /* #if defined (ARM_MATH_LOOPUNROLL) */

while (blkCnt > 0U)
  {
    /* C = A + B */

/* Add and store result in destination buffer. */
    *pDst++ = (_Float16)(*pSrcA++) + (_Float16)(*pSrcB++);

/* Decrement loop counter */
    blkCnt--;
  }

}
