    blkCnt = blockSize & 0x7;
    if (blkCnt > 0U)
    {
      /* C = |A| */
      mve_pred16_t p0 = vctp16q(blkCnt);
      vec1 = vld1q((float16_t const *) pSrc);
      vstrhq_p(pDst, vnegq(vec1), p0);
