while (blkCnt > 0U)
  {
    /* C = A - B */

/* Subtract and store result in destination buffer. */
    *pDst++ = (*pSrcA++) - (*pSrcB++);

*pDst++ = (*pSrcA++) - (*pSrcB++);

*pDst++ = (*pSrcA++) - (*pSrcB++);

*pDst++ = (*pSrcA++) - (*pSrcB++);

