    {
        vecSrcA = vld1q(pSrcA);
        vecSrcB = vld1q(pSrcB);

vst1q(pDst, veorq_u32(vecSrcA, vecSrcB) );

pSrcA += 4;
        pSrcB += 4;
        pDst  += 4;

