        blkCnt--;
    }

/* Tail */
    blkCnt = blockSize & 3;

if (blkCnt > 0U)
    {
        mve_pred16_t p0 = vctp32q(blkCnt);
        vecSrcA = vld1q(pSrcA);
        vecSrcB = vld1q(pSrcB);
        vstrwq_p(pDst, veorq_u32(vecSrcA, vecSrcB), p0);
    }
#else
