    {
        vecA = vld1q_u32(pSrcA);
        vecB = vld1q_u32(pSrcB);

vst1q_u32(pDst, veorq_u32(vecA, vecB) );

pSrcA += 4;
        pSrcB += 4;
        pDst  += 4;

/* Decrement the loop counter */
        blkCnt--;
    }

/* Tail */
    blkCnt = blockSize & 3;
#else
    /* Initialize blkCnt with number of samples */
    blkCnt = blockSize;
#endif

while (blkCnt > 0U)
    {
        *pDst++ = (*pSrcA++)^(*pSrcB++);

/* Decrement the loop counter */
        blkCnt--;
    }
#endif /* if defined(ARM_MATH_MVEI) */
}

