        b = vld1q_f32(pB);

c = vabdq_f32(a,b);
        accumDiffV = vaddq_f32(accumDiffV,c);

c = vaddq_f32(a,b);
        c = vabsq_f32(c);
        accumSumV = vaddq_f32(accumSumV,c);

pA += 4;
        pB += 4;
        blkCnt --;
