   accumDiff = vget_lane_f32(accumV2, 0) + vget_lane_f32(accumV2, 1);

accumV2 = vpadd_f32(vget_low_f32(accumSumV),vget_high_f32(accumSumV));
   accumSum = vget_lane_f32(accumV2, 0) + vget_lane_f32(accumV2, 1);

blkCnt = blockSize & 3;
   while(blkCnt > 0)
