        a = vreinterpretq_f32_s32(vbicq_s32(vreinterpretq_s32_f32(a),vreinterpretq_s32_u32(isZeroV)));
        c = vmulq_f32(c,a);
        accumV = vaddq_f32(accumV,c);

pA += 4;
