{
   _Float16 diff=0.0f,  maxVal,tmpA, tmpB;

tmpA = *pA++;
   tmpB = *pB++;
   diff = (_Float16)fabsf((float32_t)((_Float16)tmpA - (_Float16)tmpB));
   maxVal = diff;
   blockSize--;

