      diff = (_Float16)fabsf((float32_t)((_Float16)tmpA - (_Float16)tmpB));
      if ((_Float16)diff > (_Float16)maxVal)
      {
        maxVal = diff;
      }
      blockSize --;
   }

   return(maxVal);
}
