   uint32_t blkCnt;
   float32x4_t a,b,diffV, maxValV;
   float32x2_t maxValV2;

if (blockSize <= 3)
   {
      tmpA = *pA++;
      tmpB = *pB++;
      diff = fabsf(tmpA - tmpB);
      maxVal = diff;
      blockSize--;

      while(blockSize > 0)
