}

__STATIC_FORCEINLINE float16_t arm_atan_f16(float16_t x)
{
   int sign=0;
   float16_t res=0.0f16;

if ((_Float16)x < 0.0f16)
   {
      sign=1;
      x=-(_Float16)x;
   }

