   {
      x = 1.0f16 / (_Float16)x;
      res = (_Float16)PI16HALF - (_Float16)arm_atan_limited_f16(x);
   }
   else
   {
     res += (_Float16)arm_atan_limited_f16(x);
   }

if (sign)
   {
     res = -(_Float16)res;
   }

return(res);
}

