void arm_vexp_f16(
  const float16_t * pSrc,
        float16_t * pDst,
        uint32_t blockSize)
{
   uint32_t blkCnt;

#if defined(ARM_MATH_MVE_FLOAT16) && !defined(ARM_MATH_AUTOVECTORIZE)

f16x8_t src;
   f16x8_t dst;

blkCnt = blockSize >> 3;

while (blkCnt > 0U)
   {
      src = vld1q(pSrc);
      dst = vexpq_f16(src);
      vst1q(pDst, dst);

pSrc += 8;
      pDst += 8;
      /* Decrement loop counter */
      blkCnt--;
   }

blkCnt = blockSize & 7;
#else
   blkCnt = blockSize;
#endif

while (blkCnt > 0U)
   {
      /* C = log(A) */

      /* Calculate log and store result in destination buffer. */
      *pDst++ = (_Float16)expf((float32_t)*pSrc++);

      /* Decrement loop counter */
      blkCnt--;
   }
}

