    acc0Vec = vfmaq_m_f16(acc0Vec, xVec, yVec,p0);                                                  \
                                                                                                    \
    acc0 = vecAddAcrossF16Mve(acc0Vec);                                                             \
    acc1 = vecAddAcrossF16Mve(acc1Vec);                                                             \
}

\
