        q31_t *pScr2 = pScratchOut;                    /* Working pointer for scratch buffer of output values */
        q31_t in;
        q7_t coeff = *pCoeffs++;                       /* Read the coefficient value */

#if defined (ARM_MATH_LOOPUNROLL)
        q7_t in1, in2, in3, in4;
#endif

