/**
  @} end of LD group
 */

@par
                   After each sample of the error signal is computed, the filter coefficients <code>b[k]</code> are updated on a sample-by-sample basis:
  <pre>
      b[k] = b[k] + e[n] * mu * x[n-k],  for k=0, 1, ..., numTaps-1
  </pre>
                   where <code>mu</code> is the step size and controls the rate of coefficient convergence.
  @par
                   In the APIs, <code>pCoeffs</code> points to a coefficient array of size <code>numTaps</code>.
                   Coefficients are stored in time reversed order.
  @par
  <pre>
     {b[numTaps-1], b[numTaps-2], b[N-2], ..., b[1], b[0]}
  </pre>
  @par
                   <code>pState</code> points to a state array of size <code>numTaps + blockSize - 1</code>.
                   Samples in the state buffer are stored in the order:
  @par
  <pre>
     {x[n-numTaps+1], x[n-numTaps], x[n-numTaps-1], x[n-numTaps-2]....x[0], x[1], ..., x[blockSize-1]}
  </pre>
  @par
                   Note that the length of the state buffer exceeds the length of the coefficient array by <code>blockSize-1</code> samples.
                   The increased state buffer length allows circular addressing, which is traditionally used in FIR filters,
                   to be avoided and yields a significant speed improvement.
                   The state variables are updated after each block of data is processed.
  @par           Instance Structure
                   The coefficients and state variables for a filter are stored together in an instance data structure.
                   A separate instance structure must be defined for each filter and
                   coefficient and state arrays cannot be shared among instances.
                   There are separate instance structure declarations for each of the 3 supported data types.

@par           Scaling of Coefficients
                   Filter coefficients are represented as fractional values and
                   coefficients are restricted to lie in the range <code>[-1 +1)</code>.
                   The fixed-point functions have an additional scaling parameter <code>postShift</code>.
                   At the output of the filter's accumulator is a shift register which shifts the result by <code>postShift</code> bits.
                   This essentially scales the filter coefficients by <code>2^postShift</code> and
                   allows the filter coefficients to exceed the range <code>[+1 -1)</code>.
                   The value of <code>postShift</code> is set by the user based on the expected gain through the system being modeled.

@par           Overflow and Saturation
                   Overflow and saturation behavior of the fixed-point Q15 and Q31 versions are
                   described separately as part of the function specific documentation below.
 */

/**
  @addtogroup LMS
  @{
 */

/**
  @brief         Processing function for floating-point LMS filter.
  @param[in]     S          points to an instance of the floating-point LMS filter structure
  @param[in]     pSrc       points to the block of input data
  @param[in]     pRef       points to the block of reference data
  @param[out]    pOut       points to the block of output data
  @param[out]    pErr       points to the block of error data
  @param[in]     blockSize  number of samples to process
  @return        none
 */
#if defined(ARM_MATH_NEON)
void arm_lms_f32(
  const arm_lms_instance_f32 * S,
  const float32_t * pSrc,
  float32_t * pRef,
  float32_t * pOut,
  float32_t * pErr,
  uint32_t blockSize)
{
  float32_t *pState = S->pState;                 /* State pointer */
  float32_t *pCoeffs = S->pCoeffs;               /* Coefficient pointer */
  float32_t *pStateCurnt;                        /* Points to the current sample of the state */
  float32_t *px, *pb;                            /* Temporary pointers for state and coefficient buffers */
  float32_t mu = S->mu;                          /* Adaptive factor */
  uint32_t numTaps = S->numTaps;                 /* Number of filter coefficients in the filter */
  uint32_t tapCnt, blkCnt;                       /* Loop counters */
  float32_t sum, e, d;                           /* accumulator, error, reference data sample */
  float32_t w = 0.0f;                            /* weight factor */

float32x4_t tempV, sumV, xV, bV;
  float32x2_t tempV2;

e = 0.0f;
  d = 0.0f;

/* S->pState points to state array which contains previous frame (numTaps - 1) samples */
  /* pStateCurnt points to the location where the new input data should be written */
  pStateCurnt = &(S->pState[(numTaps - 1U)]);

blkCnt = blockSize;

while (blkCnt > 0U)
  {
    /* Copy the new input sample into the state buffer */
    *pStateCurnt++ = *pSrc++;

/* Initialize pState pointer */
    px = pState;

/* Initialize coeff pointer */
    pb = (pCoeffs);

/* Set the accumulator to zero */
    sum = 0.0f;
    sumV = vdupq_n_f32(0.0);

/* Process 4 taps at a time. */
    tapCnt = numTaps >> 2;

while (tapCnt > 0U)
    {
      /* Perform the multiply-accumulate */
      xV = vld1q_f32(px);
      bV = vld1q_f32(pb);
      sumV = vmlaq_f32(sumV, xV, bV);

px += 4; 
      pb += 4;

/* Decrement the loop counter */
      tapCnt--;
    }
    tempV2 = vpadd_f32(vget_low_f32(sumV),vget_high_f32(sumV));
    sum = vget_lane_f32(tempV2, 0) + vget_lane_f32(tempV2, 1);

/* If the filter length is not a multiple of 4, compute the remaining filter taps */
    tapCnt = numTaps % 0x4U;

while (tapCnt > 0U)
    {
      /* Perform the multiply-accumulate */
      sum += (*px++) * (*pb++);

/* Decrement the loop counter */
      tapCnt--;
    }

/* The result in the accumulator, store in the destination buffer. */
    *pOut++ = sum;

/* Compute and store error */
    d = (float32_t) (*pRef++);
    e = d - sum;
    *pErr++ = e;

/* Calculation of Weighting factor for the updating filter coefficients */
    w = e * mu;

/* Initialize pState pointer */
    px = pState;

/* Initialize coeff pointer */
    pb = (pCoeffs);

/* Process 4 taps at a time. */
    tapCnt = numTaps >> 2;

/* Update filter coefficients */
    while (tapCnt > 0U)
    {
      /* Perform the multiply-accumulate */
      xV = vld1q_f32(px);
      bV = vld1q_f32(pb);
      px += 4;
      bV = vmlaq_n_f32(bV,xV,w);

vst1q_f32(pb,bV); 
      pb += 4;

/* Decrement the loop counter */
      tapCnt--;
    }

/* If the filter length is not a multiple of 4, compute the remaining filter taps */
    tapCnt = numTaps % 0x4U;

while (tapCnt > 0U)
    {
      /* Perform the multiply-accumulate */
      *pb = *pb + (w * (*px++));
      pb++;

/* Decrement the loop counter */
      tapCnt--;
    }

/* Advance state pointer by 1 for the next sample */
    pState = pState + 1;

/* Decrement the loop counter */
    blkCnt--;
  }

/* Processing is complete. Now copy the last numTaps - 1 samples to the
     satrt of the state buffer. This prepares the state buffer for the
     next function call. */

/* Points to the start of the pState buffer */
  pStateCurnt = S->pState;

/* Process 4 taps at a time for (numTaps - 1U) samples copy */
  tapCnt = (numTaps - 1U) >> 2U;

/* copy data */
  while (tapCnt > 0U)
  {
    tempV = vld1q_f32(pState);
    vst1q_f32(pStateCurnt,tempV); 
    pState += 4;
    pStateCurnt += 4;

/* Decrement the loop counter */
    tapCnt--;
  }

/* Calculate remaining number of copies */
  tapCnt = (numTaps - 1U) % 0x4U;

/* Copy the remaining q31_t data */
  while (tapCnt > 0U)
  {
    *pStateCurnt++ = *pState++;

/* Decrement the loop counter */
    tapCnt--;
  }

}
#else
void arm_lms_f32(
  const arm_lms_instance_f32 * S,
  const float32_t * pSrc,
        float32_t * pRef,
        float32_t * pOut,
        float32_t * pErr,
        uint32_t blockSize)
{       
        float32_t *pState = S->pState;                 /* State pointer */
        float32_t *pCoeffs = S->pCoeffs;               /* Coefficient pointer */
        float32_t *pStateCurnt;                        /* Points to the current sample of the state */
        float32_t *px, *pb;                            /* Temporary pointers for state and coefficient buffers */
        float32_t mu = S->mu;                          /* Adaptive factor */
        float32_t acc, e;                              /* Accumulator, error */
        float32_t w;                                   /* Weight factor */
        uint32_t numTaps = S->numTaps;                 /* Number of filter coefficients in the filter */
        uint32_t tapCnt, blkCnt;                       /* Loop counters */

/* Initializations of error,  difference, Coefficient update */
  e = 0.0f;
  w = 0.0f;

/* S->pState points to state array which contains previous frame (numTaps - 1) samples */
  /* pStateCurnt points to the location where the new input data should be written */
  pStateCurnt = &(S->pState[(numTaps - 1U)]);

/* initialise loop count */
  blkCnt = blockSize;

while (blkCnt > 0U)
  {
    /* Copy the new input sample into the state buffer */
    *pStateCurnt++ = *pSrc++;

/* Initialize pState pointer */
    px = pState;

/* Initialize coefficient pointer */
    pb = pCoeffs;

/* Set the accumulator to zero */
    acc = 0.0f;

#if defined (ARM_MATH_LOOPUNROLL)

/* Loop unrolling: Compute 4 taps at a time. */
    tapCnt = numTaps >> 2U;

while (tapCnt > 0U)
    {
      /* Perform the multiply-accumulate */
      acc += (*px++) * (*pb++);

acc += (*px++) * (*pb++);

acc += (*px++) * (*pb++);

acc += (*px++) * (*pb++);

/* Decrement loop counter */
      tapCnt--;
    }

/* Loop unrolling: Compute remaining taps */
    tapCnt = numTaps % 0x4U;

#else

/* Initialize tapCnt with number of samples */
    tapCnt = numTaps;

#endif /* #if defined (ARM_MATH_LOOPUNROLL) */

while (tapCnt > 0U)
    {
      /* Perform the multiply-accumulate */
      acc += (*px++) * (*pb++);

/* Decrement the loop counter */
      tapCnt--;
    }

/* Store the result from accumulator into the destination buffer. */
    *pOut++ = acc;

/* Compute and store error */
    e = (float32_t) *pRef++ - acc;
    *pErr++ = e;

/* Calculation of Weighting factor for updating filter coefficients */
    w = e * mu;

/* Initialize pState pointer */
    /* Advance state pointer by 1 for the next sample */
    px = pState++;

/* Initialize coefficient pointer */
    pb = pCoeffs;

#if defined (ARM_MATH_LOOPUNROLL)

/* Loop unrolling: Compute 4 taps at a time. */
    tapCnt = numTaps >> 2U;

/* Update filter coefficients */
    while (tapCnt > 0U)
    {
      /* Perform the multiply-accumulate */
      *pb += w * (*px++);
      pb++;

*pb += w * (*px++);
      pb++;

*pb += w * (*px++);
      pb++;

*pb += w * (*px++);
      pb++;

/* Decrement loop counter */
      tapCnt--;
    }

/* Loop unrolling: Compute remaining taps */
    tapCnt = numTaps % 0x4U;

#else

/* Initialize tapCnt with number of samples */
    tapCnt = numTaps;

#endif /* #if defined (ARM_MATH_LOOPUNROLL) */

while (tapCnt > 0U)
    {
      /* Perform the multiply-accumulate */
      *pb += w * (*px++);
      pb++;

/* Decrement loop counter */
      tapCnt--;
    }

/* Decrement loop counter */
    blkCnt--;
  }

/* Processing is complete.
     Now copy the last numTaps - 1 samples to the start of the state buffer.
     This prepares the state buffer for the next function call. */

/* Points to the start of the pState buffer */
  pStateCurnt = S->pState;

/* copy data */
#if defined (ARM_MATH_LOOPUNROLL)

/* Loop unrolling: Compute 4 taps at a time. */
  tapCnt = (numTaps - 1U) >> 2U;

while (tapCnt > 0U)
  {
    *pStateCurnt++ = *pState++;
    *pStateCurnt++ = *pState++;
    *pStateCurnt++ = *pState++;
    *pStateCurnt++ = *pState++;

/* Decrement loop counter */
    tapCnt--;
  }

/* Loop unrolling: Compute remaining taps */
  tapCnt = (numTaps - 1U) % 0x4U;

#else

/* Initialize tapCnt with number of samples */
  tapCnt = (numTaps - 1U);

#endif /* #if defined (ARM_MATH_LOOPUNROLL) */

while (tapCnt > 0U)
  {
    *pStateCurnt++ = *pState++;

/* Decrement loop counter */
    tapCnt--;
  }

}
