/**
  @brief         Processing function for floating-point normalized LMS filter.
  @param[in]     S         points to an instance of the floating-point normalized LMS filter structure
  @param[in]     pSrc      points to the block of input data
  @param[in]     pRef      points to the block of reference data
  @param[out]    pOut      points to the block of output data
  @param[out]    pErr      points to the block of error data
  @param[in]     blockSize number of samples to process
  @return        none
 */

#if defined(ARM_MATH_NEON)
void arm_lms_norm_f32(
  arm_lms_norm_instance_f32 * S,
  const float32_t * pSrc,
  float32_t * pRef,
  float32_t * pOut,
  float32_t * pErr,
  uint32_t blockSize)
{
  float32_t *pState = S->pState;                 /* State pointer */
  float32_t *pCoeffs = S->pCoeffs;               /* Coefficient pointer */
  float32_t *pStateCurnt;                        /* Points to the current sample of the state */
  float32_t *px, *pb;                            /* Temporary pointers for state and coefficient buffers */
  float32_t mu = S->mu;                          /* Adaptive factor */
  uint32_t numTaps = S->numTaps;                 /* Number of filter coefficients in the filter */
  uint32_t tapCnt, blkCnt;                       /* Loop counters */
  float32_t energy;                              /* Energy of the input */
  float32_t sum, e, d;                           /* accumulator, error, reference data sample */
  float32_t w, x0, in;                           /* weight factor, temporary variable to hold input sample and state */

float32x4_t tempV, sumV, xV, bV;
  float32x2_t tempV2;

/* Initializations of error,  difference, Coefficient update */
  e = 0.0f;
  d = 0.0f;
  w = 0.0f;

energy = S->energy;
  x0 = S->x0;

/* S->pState points to buffer which contains previous frame (numTaps - 1) samples */
  /* pStateCurnt points to the location where the new input data should be written */
  pStateCurnt = &(S->pState[(numTaps - 1U)]);

/* Loop over blockSize number of values */
  blkCnt = blockSize;

while (blkCnt > 0U)
  {
    /* Copy the new input sample into the state buffer */
    *pStateCurnt++ = *pSrc;

/* Initialize pState pointer */
    px = pState;

/* Initialize coeff pointer */
    pb = (pCoeffs);

/* Read the sample from input buffer */
    in = *pSrc++;

/* Update the energy calculation */
    energy -= x0 * x0;
    energy += in * in;

/* Set the accumulator to zero */
    sum = 0.0f;
    sumV = vdupq_n_f32(0.0);

/* Process 4 taps at a time. */
    tapCnt = numTaps >> 2;

while (tapCnt > 0U)
    {
      /* Perform the multiply-accumulate */
      xV = vld1q_f32(px);
      bV = vld1q_f32(pb);
      sumV = vmlaq_f32(sumV, xV, bV);

px += 4; 
      pb += 4;

/* Decrement the loop counter */
      tapCnt--;
    }
    tempV2 = vpadd_f32(vget_low_f32(sumV),vget_high_f32(sumV));
    sum = vget_lane_f32(tempV2, 0) + vget_lane_f32(tempV2, 1);

/* If the filter length is not a multiple of 4, compute the remaining filter taps */
    tapCnt = numTaps % 0x4U;

while (tapCnt > 0U)
    {
      /* Perform the multiply-accumulate */
      sum += (*px++) * (*pb++);

/* Decrement the loop counter */
      tapCnt--;
    }

/* The result in the accumulator, store in the destination buffer. */
    *pOut++ = sum;

/* Compute and store error */
    d = (float32_t) (*pRef++);
    e = d - sum;
    *pErr++ = e;

/* Calculation of Weighting factor for updating filter coefficients */
    /* epsilon value 0.000000119209289f */
    w = (e * mu) / (energy + 0.000000119209289f);

/* Initialize pState pointer */
    px = pState;

/* Initialize coeff pointer */
    pb = (pCoeffs);

/* Process 4 taps at a time. */
    tapCnt = numTaps >> 2;

/* Update filter coefficients */
    while (tapCnt > 0U)
    {
      /* Perform the multiply-accumulate */
      xV = vld1q_f32(px);
      bV = vld1q_f32(pb);
      px += 4;
      bV = vmlaq_n_f32(bV,xV,w);

vst1q_f32(pb,bV); 
      pb += 4;

/* Decrement the loop counter */
      tapCnt--;
    }

/* If the filter length is not a multiple of 4, compute the remaining filter taps */
    tapCnt = numTaps % 0x4U;

while (tapCnt > 0U)
    {
      /* Perform the multiply-accumulate */
      *pb += w * (*px++);
      pb++;

/* Decrement the loop counter */
      tapCnt--;
    }

x0 = *pState;

/* Advance state pointer by 1 for the next sample */
    pState = pState + 1;

/* Decrement the loop counter */
    blkCnt--;
  }

S->energy = energy;
  S->x0 = x0;

/* Processing is complete. Now copy the last numTaps - 1 samples to the
     satrt of the state buffer. This prepares the state buffer for the
     next function call. */

/* Points to the start of the pState buffer */
  pStateCurnt = S->pState;

/* Process 4 taps at a time for (numTaps - 1U)/4 samples copy */
  tapCnt = (numTaps - 1U) >> 2U;

/* copy data */
  while (tapCnt > 0U)
  {
    tempV = vld1q_f32(pState);
    vst1q_f32(pStateCurnt,tempV); 
    pState += 4;
    pStateCurnt += 4;

/* Decrement the loop counter */
    tapCnt--;
  }

/* Calculate remaining number of copies */
  tapCnt = (numTaps - 1U) % 0x4U;

/* Copy the remaining q31_t data */
  while (tapCnt > 0U)
  {
    *pStateCurnt++ = *pState++;

/* Decrement the loop counter */
    tapCnt--;
  }

}
