    blkCnt = numSamples;

#endif /* #if defined (ARM_MATH_LOOPUNROLL) */

while (blkCnt > 0U)
    {
      /* C(m,n) = A(m,n) + B(m,n) */

/* Add, saturate and store result in destination buffer. */
#if defined (ARM_MATH_DSP)
