            float32_t const *pInA1 = pInA0 + numColsA * CMPLX_DIM;
            float32_t const *pInA2 = pInA1 + numColsA * CMPLX_DIM;
            float32_t const *pInA3 = pInA2 + numColsA * CMPLX_DIM;
