         * column loop
         */
        while (col > 0u)
        {
            /*
             * generate 4 columns elements
             */
            /*
             * Matrix A columns number of MAC operations are to be performed
             */

float32_t const *pSrcA0Vec;
            float32_t const *pInA0 = pInA;
            f32x4_t acc0;

acc0 = vdupq_n_f32(0.0f);

pSrcA0Vec = (float32_t const *) pInA0;

