/**
 * @brief Q31 matrix and vector multiplication.
 * @param[in]       *pSrcMat points to the input matrix structure
 * @param[in]       *pVec points to the input vector
 * @param[out]      *pDst points to the output vector
 */
#if defined(ARM_MATH_MVEI) && !defined(ARM_MATH_AUTOVECTORIZE)
void arm_mat_vec_mult_q31(
    const arm_matrix_instance_q31 * pSrcMat,
    const q31_t     *pSrcVec,
    q31_t           *pDstVec)
{
    const q31_t *pMatSrc = pSrcMat->pData;
    const q31_t *pMat0, *pMat1;
    uint32_t     numRows = pSrcMat->numRows;
    uint32_t     numCols = pSrcMat->numCols;
    q31_t       *px;
    int32_t      row;
    uint16_t     blkCnt;           /* loop counters */

row = numRows;
    px = pDstVec;

/*
     * compute 3x64-bit accumulators per loop
     */
    while (row >= 3)
    {
        q31_t const *pMat0Vec, *pMat1Vec, *pMat2Vec, *pVec;
        const q31_t  *pMat2;
        q31_t const  *pSrcVecPtr = pSrcVec;
        q63_t         acc0, acc1, acc2;
        q31x4_t     vecMatA0, vecMatA1, vecMatA2, vecIn;

pVec = pSrcVec;
        /*
         * Initialize the pointer pIn1 to point to the starting address of the column being processed
         */
        pMat0 = pMatSrc;
        pMat1 = pMat0 + numCols;
        pMat2 = pMat1 + numCols;

acc0 = 0LL;
        acc1 = 0LL;
        acc2 = 0LL;

pMat0Vec = pMat0;
        pMat1Vec = pMat1;
        pMat2Vec = pMat2;
        pVec = pSrcVecPtr;

blkCnt = numCols >> 2;
        while (blkCnt > 0U)
        {
            vecMatA0 = vld1q(pMat0Vec); 
            pMat0Vec += 4;
            vecMatA1 = vld1q(pMat1Vec); 
            pMat1Vec += 4;
            vecMatA2 = vld1q(pMat2Vec); 
            pMat2Vec += 4;
            vecIn = vld1q(pVec);        
            pVec += 4;

acc0 = vmlaldavaq(acc0, vecIn, vecMatA0);
            acc1 = vmlaldavaq(acc1, vecIn, vecMatA1);
            acc2 = vmlaldavaq(acc2, vecIn, vecMatA2);

blkCnt--;
        }
        /*
         * tail
         * (will be merged thru tail predication)
         */
        blkCnt = numCols & 3;
        if (blkCnt > 0U)
        {
            mve_pred16_t p0 = vctp32q(blkCnt);

vecMatA0 = vld1q(pMat0Vec);
            vecMatA1 = vld1q(pMat1Vec);
            vecMatA2 = vld1q(pMat2Vec);
            vecIn = vldrwq_z_s32(pVec, p0);

acc0 = vmlaldavaq(acc0, vecIn, vecMatA0);
            acc1 = vmlaldavaq(acc1, vecIn, vecMatA1);
            acc2 = vmlaldavaq(acc2, vecIn, vecMatA2);
        }

*px++ = asrl(acc0, 31);
        *px++ = asrl(acc1, 31);
        *px++ = asrl(acc2, 31);

pMatSrc += numCols * 3;
        /*
         * Decrement the row loop counter
         */
        row -= 3;
    }

/*
     * process any remaining rows pair
     */
    if (row >= 2)
    {
        q31_t const *pMat0Vec, *pMat1Vec, *pVec;
        q31_t const  *pSrcVecPtr = pSrcVec;
        q63_t         acc0, acc1;
        q31x4_t     vecMatA0, vecMatA1, vecIn;

/*
         * For every row wise process, the pInVec pointer is set
         * to the starting address of the vector
         */
        pVec = pSrcVec;

/*
         * Initialize the pointer pIn1 to point to the starting address of the column being processed
         */
        pMat0 = pMatSrc;
        pMat1 = pMat0 + numCols;

acc0 = 0LL;
        acc1 = 0LL;

pMat0Vec = pMat0;
        pMat1Vec = pMat1;
        pVec = pSrcVecPtr;

blkCnt = numCols >> 2;
        while (blkCnt > 0U)
        {
            vecMatA0 = vld1q(pMat0Vec); 
            pMat0Vec += 4;
            vecMatA1 = vld1q(pMat1Vec); 
            pMat1Vec += 4;
            vecIn = vld1q(pVec);        
            pVec += 4;

acc0 = vmlaldavaq(acc0, vecIn, vecMatA0);
            acc1 = vmlaldavaq(acc1, vecIn, vecMatA1);

blkCnt--;
        }

/*
         * tail
         * (will be merged thru tail predication)
         */
        blkCnt = numCols & 3;
        if (blkCnt > 0U)
        {
            mve_pred16_t p0 = vctp32q(blkCnt);

vecMatA0 = vld1q(pMat0Vec);
            vecMatA1 = vld1q(pMat1Vec);
            vecIn = vldrwq_z_s32(pVec, p0);

acc0 = vmlaldavaq(acc0, vecIn, vecMatA0);
            acc1 = vmlaldavaq(acc1, vecIn, vecMatA1);
        }

*px++ = asrl(acc0, 31);
        *px++ = asrl(acc1, 31);

pMatSrc += numCols * 2;
        /*
         * Decrement the row loop counter
         */
        row -= 2;
    }

if (row >= 1)
    {
        q31_t const *pMat0Vec, *pVec;
        q31_t const  *pSrcVecPtr = pSrcVec;
        q63_t         acc0;
        q31x4_t     vecMatA0, vecIn;

/*
         * For every row wise process, the pInVec pointer is set
         * to the starting address of the vector
         */
        pVec = pSrcVec;

/*
         * Initialize the pointer pIn1 to point to the starting address of the column being processed
         */
        pMat0 = pMatSrc;

acc0 = 0LL;

pMat0Vec = pMat0;
        pVec = pSrcVecPtr;

blkCnt = numCols >> 2;
        while (blkCnt > 0U)
        {
            vecMatA0 = vld1q(pMat0Vec); 
            pMat0Vec += 4;
            vecIn = vld1q(pVec);        
            pVec += 4;
            acc0 = vmlaldavaq(acc0, vecIn, vecMatA0);
            blkCnt--;
        }
        /*
         * tail
         * (will be merged thru tail predication)
         */
        blkCnt = numCols & 3;
        if (blkCnt > 0U)
        {
            mve_pred16_t p0 = vctp32q(blkCnt);

vecMatA0 = vld1q(pMat0Vec);
            vecIn = vldrwq_z_s32(pVec, p0);
            acc0 = vmlaldavaq(acc0, vecIn, vecMatA0);
        }

*px++ = asrl(acc0, 31);
    }
}
