        pMat0 = pMatSrc;
        pMat1 = pMat0 + numCols;
        pMat2 = pMat1 + numCols;
        pMat3 = pMat2 + numCols;

acc0 = 0L;
        acc1 = 0L;
        acc2 = 0L;
        acc3 = 0L;

pMat0Vec = pMat0;
        pMat1Vec = pMat1;
        pMat2Vec = pMat2;
        pMat3Vec = pMat3;
        pVec = pSrcVecPtr;

