{
    const float16_t *pIn;
    uint32_t blkCnt;
    _Float16 accum, p;

    pIn = pSrcA;
    blkCnt = blockSize;

accum = 0.0f;

while(blkCnt > 0)
    {
       p = *pIn++;
       accum += p * (_Float16)logf((float32_t)p);

       blkCnt--;

    }

return(-accum);
}
