float32_t arm_entropy_f32(const float32_t * pSrcA,uint32_t blockSize)
{
    const float32_t *pIn;
    uint32_t blkCnt;
    float32_t accum, p;

float32x4_t accumV;
    float32x2_t accumV2;
    float32x4_t tmpV, tmpV2;

    pIn = pSrcA;

accum = 0.0f;
    accumV = vdupq_n_f32(0.0f);

blkCnt = blockSize >> 2;
    while(blkCnt > 0)
    {
      tmpV = vld1q_f32(pIn);
      pIn += 4;

tmpV2 = vlogq_f32(tmpV);
      accumV = vmlaq_f32(accumV, tmpV, tmpV2);

