/**
  @addtogroup Max
  @{
 */

/**
  @brief         Maximum value of a q15 vector without index.
  @param[in]     pSrc       points to the input vector
  @param[in]     blockSize  number of samples in input vector
  @param[out]    pResult    maximum value returned here
  @return        none
 */

#if defined(ARM_MATH_MVEI) && !defined(ARM_MATH_AUTOVECTORIZE)

#include "arm_helium_utils.h"

void arm_max_no_idx_q15(
  const q15_t * pSrc,
        uint32_t blockSize,
        q15_t * pResult)
{
    int32_t  blkCnt;           /* loop counters */
    q15x8_t       vecSrc;
    q15_t const *pSrcVec;
    q15x8_t       curExtremValVec = vdupq_n_s16(Q15_MIN);
    q15_t           maxValue = Q15_MIN;
    mve_pred16_t    p0;

#else
void arm_max_no_idx_q15(
  const q15_t * pSrc,
        uint32_t blockSize,
        q15_t * pResult)
{
  q15_t maxVal1, out;       /* Temporary variables to store the output value. */     
  uint32_t blkCnt;              /* loop counter */                                 

  /* Load first input value that act as reference value for comparision */         
  out = *pSrc++;                                                                   

  blkCnt = (blockSize - 1U);                                                       


  while (blkCnt > 0U)                                                              
  {                                                                                
    /* Initialize maxVal to the next consecutive values one by one */              
    maxVal1 = *pSrc++;                                                             

    /* compare for the maximum value */                                            
    if (out < maxVal1)                                                             
    {                                                                              
      /* Update the maximum value */                                               
      out = maxVal1;                                                               
    }                                                                              

    /* Decrement the loop counter */                                               
    blkCnt--;

pSrcVec = (q15_t const *) pSrc;
    blkCnt = blockSize >> 3;
    while (blkCnt > 0)
    {
        vecSrc = vld1q(pSrcVec); 
        pSrcVec += 8;
        /*
         * update per-lane max.
         */
        curExtremValVec = vmaxq(vecSrc, curExtremValVec);
        /*
         * Decrement the blockSize loop counter
         */
        blkCnt--;
    }
    /*
     * tail
     * (will be merged thru tail predication)
     */
    blkCnt = blockSize & 7;
    if (blkCnt > 0)
    {
        vecSrc = vld1q(pSrcVec); 
        pSrcVec += 8;
        p0 = vctp16q(blkCnt);
