/**
  @brief         Mean square error between two Q15 vectors.
  @param[in]     pSrcA       points to the first input vector
  @param[in]     pSrcB       points to the second input vector
  @param[in]     blockSize   number of samples in input vector
  @param[out]    pResult     mean square error
  @return        none
 */
#if defined(ARM_MATH_MVEI) && !defined(ARM_MATH_AUTOVECTORIZE)
void arm_mse_q15(
  const q15_t * pSrcA,
  const q15_t * pSrcB,
        uint32_t blockSize,
        q15_t * pResult)
{
    uint32_t  blkCnt;           /* loop counters */
    q15x8_t vecSrcA,vecSrcB;
    q63_t   sum = 0LL;

blkCnt = blockSize >> 3U;
    while (blkCnt > 0U)
    {
        vecSrcA = vld1q(pSrcA);
        vecSrcB = vld1q(pSrcB);

vecSrcA = vshrq(vecSrcA,1);
        vecSrcB = vshrq(vecSrcB,1);

vecSrcA = vqsubq(vecSrcA,vecSrcB);
        /*
         * sum lanes
         */
        sum = vmlaldavaq(sum, vecSrcA, vecSrcA);

blkCnt--;
        pSrcA += 8;
        pSrcB += 8;
    }

/*
     * tail
     */
    blkCnt = blockSize & 7;
    if (blkCnt > 0U)
    {
        mve_pred16_t p0 = vctp16q(blkCnt);
        vecSrcA = vld1q(pSrcA);
        vecSrcB = vld1q(pSrcB);

vecSrcA = vshrq(vecSrcA,1);
        vecSrcB = vshrq(vecSrcB,1);

vecSrcA = vqsubq(vecSrcA,vecSrcB);

sum = vmlaldavaq_p(sum, vecSrcA, vecSrcA, p0);
    }

*pResult = (q15_t) __SSAT((q31_t) (sum / blockSize)>>13, 16);
}
#else
void arm_mse_q15(
  const q15_t * pSrcA,
  const q15_t * pSrcB,
        uint32_t blockSize,
        q15_t * pResult)
{
        uint32_t blkCnt;                               /* Loop counter */
        q63_t sum = 0;                                 /* Temporary result storage */
        q15_t inA,inB;                                       /* Temporary variable to store input value */

#if defined (ARM_MATH_LOOPUNROLL)

/* Loop unrolling: Compute 4 outputs at a time */
  blkCnt = blockSize >> 2U;

while (blkCnt > 0U)
  {

inA = *pSrcA++ >> 1;
    inB = *pSrcB++ >> 1;
    inA = (q15_t) __SSAT(((q31_t) inA - (q31_t)inB), 16);
    sum += (q63_t)((q31_t) inA * inA);

inA = *pSrcA++ >> 1;
    inB = *pSrcB++ >> 1;
    inA = (q15_t) __SSAT(((q31_t) inA - (q31_t)inB), 16);
    sum += (q63_t)((q31_t) inA * inA);

inA = *pSrcA++ >> 1;
    inB = *pSrcB++ >> 1;
    inA = (q15_t) __SSAT(((q31_t) inA - (q31_t)inB), 16);
    sum += (q63_t)((q31_t) inA * inA);

inA = *pSrcA++ >> 1;
    inB = *pSrcB++ >> 1;
    inA = (q15_t) __SSAT(((q31_t) inA - (q31_t)inB), 16);
    sum += (q63_t)((q31_t) inA * inA);

/* Decrement loop counter */
    blkCnt--;
  }

/* Loop unrolling: Compute remaining outputs */
  blkCnt = blockSize % 0x4U;

#else

/* Initialize blkCnt with number of samples */
  blkCnt = blockSize;

#endif /* #if defined (ARM_MATH_LOOPUNROLL) */

while (blkCnt > 0U)
  {

inA = *pSrcA++ >> 1;
    inB = *pSrcB++ >> 1;
    inA = (q15_t) __SSAT(((q31_t) inA - (q31_t)inB), 16);
    sum += (q63_t)((q31_t) inA * inA);

/* Decrement loop counter */
    blkCnt--;
  }

/* Store result in q15 format */
  *pResult = (q15_t) __SSAT((q31_t) (sum / blockSize)>>13, 16);
}
#endif /* defined(ARM_MATH_MVEI) */

