  while (blkCnt > 0U)
  {
      vstrhq_s16(pDst,vldrhq_s16(pSrc));
      /*
       * Decrement the blockSize loop counter
       * Advance vector source and destination pointers
       */
      pSrc += 8;
      pDst += 8;
      blkCnt --;
  }

blkCnt = blockSize & 7;
  while (blkCnt > 0U)
  {
    /* C = A */

