in the public headers.

This function should at some point be moved in FastMath.

*/
__STATIC_INLINE float16_t arm_exponent_f16(float16_t x, int32_t nb)
{
    float16_t r = x;
    nb --;
    while(nb > 0)
    {
        r = (_Float16)r * (_Float16)x;
        nb--;
    }
    return(r);
}
