/* ----------------------------------------------------------------
   * Step1: Re-ordering of even and odd elements as
   *             pState[i] =  pInlineBuffer[2*i] and
   *             pState[N-i-1] = pInlineBuffer[2*i+1] where i = 0 to N/2
   ---------------------------------------------------------------------*/

/* pS1 initialized to pState */
  pS1 = pState;

/* pS2 initialized to pState+N-1, so that it points to the end of the state buffer */
  pS2 = pState + (S->N - 1U);

/* pbuff initialized to input buffer */
  pbuff = pInlineBuffer;

#if defined (ARM_MATH_LOOPUNROLL)

/* Initializing the loop counter to N/2 >> 2 for loop unrolling by 4 */
  i = S->Nby2 >> 2U;

/* First part of the processing with loop unrolling.  Compute 4 outputs at a time.
   ** a second loop below computes the remaining 1 to 3 samples. */
  do
  {
    /* Re-ordering of even and odd elements */
    /* pState[i] =  pInlineBuffer[2*i] */
    *pS1++ = *pbuff++;
    /* pState[N-i-1] = pInlineBuffer[2*i+1] */
    *pS2-- = *pbuff++;

*pS1++ = *pbuff++;
    *pS2-- = *pbuff++;

*pS1++ = *pbuff++;
    *pS2-- = *pbuff++;

*pS1++ = *pbuff++;
    *pS2-- = *pbuff++;

/* Decrement loop counter */
    i--;
  } while (i > 0U);

/* pbuff initialized to input buffer */
  pbuff = pInlineBuffer;

/* pS1 initialized to pState */
  pS1 = pState;

/* Initializing the loop counter to N/4 instead of N for loop unrolling */
  i = S->N >> 2U;

/* Processing with loop unrolling 4 times as N is always multiple of 4.
   * Compute 4 outputs at a time */
  do
  {
    /* Writing the re-ordered output back to inplace input buffer */
    *pbuff++ = *pS1++;
    *pbuff++ = *pS1++;
    *pbuff++ = *pS1++;
    *pbuff++ = *pS1++;

/* Decrement the loop counter */
    i--;
  } while (i > 0U);

/* ---------------------------------------------------------
   *     Step2: Calculate RFFT for N-point input
   * ---------------------------------------------------------- */
  /* pInlineBuffer is real input of length N , pState is the complex output of length 2N */
  arm_rfft_q15 (S->pRfft, pInlineBuffer, pState);

/*----------------------------------------------------------------------
   *  Step3: Multiply the FFT output with the weights.
   *----------------------------------------------------------------------*/
  arm_cmplx_mult_cmplx_q15 (pState, weights, pState, S->N);

/* The output of complex multiplication is in 3.13 format.
   * Hence changing the format of N (i.e. 2*N elements) complex numbers to 1.15 format by shifting left by 2 bits. */
  arm_shift_q15 (pState, 2, pState, S->N * 2);

/* ----------- Post-processing ---------- */
  /* DCT-IV can be obtained from DCT-II by the equation,
   *       Y4(k) = Y2(k) - Y4(k-1) and Y4(-1) = Y4(0)
   *       Hence, Y4(0) = Y2(0)/2  */
  /* Getting only real part from the output and Converting to DCT-IV */

/* Initializing the loop counter to N >> 2 for loop unrolling by 4 */
  i = (S->N - 1U) >> 2U;

/* pbuff initialized to input buffer. */
  pbuff = pInlineBuffer;

/* pS1 initialized to pState */
  pS1 = pState;

/* Calculating Y4(0) from Y2(0) using Y4(0) = Y2(0)/2 */
  in = *pS1++ >> 1U;
  /* input buffer acts as inplace, so output values are stored in the input itself. */
  *pbuff++ = in;

/* pState pointer is incremented twice as the real values are located alternatively in the array */
  pS1++;

/* First part of the processing with loop unrolling.  Compute 4 outputs at a time.
   ** a second loop below computes the remaining 1 to 3 samples. */
  do
  {
    /* Calculating Y4(1) to Y4(N-1) from Y2 using equation Y4(k) = Y2(k) - Y4(k-1) */
    /* pState pointer (pS1) is incremented twice as the real values are located alternatively in the array */
    in = *pS1++ - in;
    *pbuff++ = in;
    /* points to the next real value */
    pS1++;

in = *pS1++ - in;
    *pbuff++ = in;
    pS1++;

in = *pS1++ - in;
    *pbuff++ = in;
    pS1++;

in = *pS1++ - in;
    *pbuff++ = in;
    pS1++;

/* Decrement the loop counter */
    i--;
  } while (i > 0U);

/* If the blockSize is not a multiple of 4, compute any remaining output samples here.
   ** No loop unrolling is used. */
  i = (S->N - 1U) % 0x4U;

while (i > 0U)
  {
    /* Calculating Y4(1) to Y4(N-1) from Y2 using equation Y4(k) = Y2(k) - Y4(k-1) */
    /* pState pointer (pS1) is incremented twice as the real values are located alternatively in the array */
    in = *pS1++ - in;
    *pbuff++ = in;

/* points to the next real value */
    pS1++;

/* Decrement loop counter */
    i--;
  }

/*------------ Normalizing the output by multiplying with the normalizing factor ----------*/

/* Initializing the loop counter to N/4 instead of N for loop unrolling */
  i = S->N >> 2U;

/* pbuff initialized to the pInlineBuffer(now contains the output values) */
  pbuff = pInlineBuffer;

/* Processing with loop unrolling 4 times as N is always multiple of 4.  Compute 4 outputs at a time */
  do
  {
    /* Multiplying pInlineBuffer with the normalizing factor sqrt(2/N) */
    in = *pbuff;
    *pbuff++ = ((q15_t) (((q31_t) in * S->normalize) >> 15));

in = *pbuff;
    *pbuff++ = ((q15_t) (((q31_t) in * S->normalize) >> 15));

in = *pbuff;
    *pbuff++ = ((q15_t) (((q31_t) in * S->normalize) >> 15));

in = *pbuff;
    *pbuff++ = ((q15_t) (((q31_t) in * S->normalize) >> 15));

/* Decrement loop counter */
    i--;
  } while (i > 0U);

#else

/* Initializing the loop counter to N/2 */
  i = S->Nby2;

do
  {
    /* Re-ordering of even and odd elements */
    /* pState[i] =  pInlineBuffer[2*i] */
    *pS1++ = *pbuff++;
    /* pState[N-i-1] = pInlineBuffer[2*i+1] */
    *pS2-- = *pbuff++;

/* Decrement the loop counter */
    i--;
  } while (i > 0U);

/* pbuff initialized to input buffer */
  pbuff = pInlineBuffer;

/* pS1 initialized to pState */
  pS1 = pState;

/* Initializing the loop counter */
  i = S->N;

do
  {
    /* Writing the re-ordered output back to inplace input buffer */
    *pbuff++ = *pS1++;

/* Decrement the loop counter */
    i--;
  } while (i > 0U);

/* ---------------------------------------------------------
   *     Step2: Calculate RFFT for N-point input
   * ---------------------------------------------------------- */
  /* pInlineBuffer is real input of length N , pState is the complex output of length 2N */
  arm_rfft_q15 (S->pRfft, pInlineBuffer, pState);

/*----------------------------------------------------------------------
   *  Step3: Multiply the FFT output with the weights.
   *----------------------------------------------------------------------*/
  arm_cmplx_mult_cmplx_q15 (pState, weights, pState, S->N);

/* The output of complex multiplication is in 3.13 format.
   * Hence changing the format of N (i.e. 2*N elements) complex numbers to 1.15 format by shifting left by 2 bits. */
  arm_shift_q15 (pState, 2, pState, S->N * 2);

/* ----------- Post-processing ---------- */
  /* DCT-IV can be obtained from DCT-II by the equation,
   *       Y4(k) = Y2(k) - Y4(k-1) and Y4(-1) = Y4(0)
   *       Hence, Y4(0) = Y2(0)/2  */
  /* Getting only real part from the output and Converting to DCT-IV */

/* pbuff initialized to input buffer. */
  pbuff = pInlineBuffer;

/* pS1 initialized to pState */
  pS1 = pState;

/* Calculating Y4(0) from Y2(0) using Y4(0) = Y2(0)/2 */
  in = *pS1++ >> 1U;
  /* input buffer acts as inplace, so output values are stored in the input itself. */
  *pbuff++ = in;

/* pState pointer is incremented twice as the real values are located alternatively in the array */
  pS1++;

/* Initializing the loop counter */
  i = (S->N - 1U);

do
  {
    /* Calculating Y4(1) to Y4(N-1) from Y2 using equation Y4(k) = Y2(k) - Y4(k-1) */
    /* pState pointer (pS1) is incremented twice as the real values are located alternatively in the array */
    in = *pS1++ - in;
    *pbuff++ = in;

/* points to the next real value */
    pS1++;

/* Decrement loop counter */
    i--;
  } while (i > 0U);

/*------------ Normalizing the output by multiplying with the normalizing factor ----------*/

/* Initializing loop counter */
  i = S->N;

/* pbuff initialized to the pInlineBuffer (now contains the output values) */
  pbuff = pInlineBuffer;

do
  {
    /* Multiplying pInlineBuffer with the normalizing factor sqrt(2/N) */
    in = *pbuff;
    *pbuff++ = ((q15_t) (((q31_t) in * S->normalize) >> 15));

/* Decrement loop counter */
    i--;

} while (i > 0U);

#endif /* #if defined (ARM_MATH_LOOPUNROLL) */

}

