    "        VMRS    R1,FPEXC          \n"
    "        ORR     R1,R1,#0x40000000 \n"
    "        VMSR    FPEXC,R1          \n"

//Initialise VFP/NEON registers to 0
    "        MOV     R2,#0             \n"

